INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Digital Workplace nur eine Software?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Tools, Prozesse und Kultur"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt ein Digital Workplace?', 3, '[{"text": "Produktivität erhöhen", "correct": true, "because": "Effizienz und Zusammenarbeit"}, {"text": "Kosten steigern", "correct": false, "because": "Ziel ist Senkung"}, {"text": "Manuelle Arbeit fördern", "correct": false, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Digital Workplace?', 5, '[{"text": "Kollaborationstools", "correct": true, "because": "Fördern Teamarbeit"}, {"text": "Cloud-Speicher", "correct": true, "because": "Flexibler Zugriff"}, {"text": "Physische Büros", "correct": false, "because": "Digital fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Digital Workplace unterstützt Remote-Arbeit. b) Er ersetzt alle physischen Arbeitsplätze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physische Plätze bleiben oft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Digital Workplace?', 4, '[{"text": "Sicherheit", "correct": false, "because": "Datenschutz essenziell"}, {"text": "Nutzerfreundlichkeit", "correct": false, "because": "Fördert Akzeptanz"}, {"text": "Büromöbel", "correct": true, "because": "Kein physischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Digital Workplace nur für IT-Teams ist?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Abteilungen"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist typisch für einen Digital Workplace?', 3, '[{"text": "Microsoft Teams", "correct": true, "because": "Fördert Kommunikation"}, {"text": "Papierakten", "correct": false, "because": "Analog"}, {"text": "Faxgerät", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Digital Workplace?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Ortsunabhängig arbeiten"}, {"text": "Verbesserte Zusammenarbeit", "correct": true, "because": "Tools vernetzen"}, {"text": "Höhere Kosten", "correct": false, "because": "Effizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Digital Workplace spart Zeit. b) Er braucht lokale Server. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud oft genutzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Digital Workplace?', 4, '[{"text": "Internet", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Kollaborationstools", "correct": false, "because": "Fördern Teamarbeit"}, {"text": "Physische Akten", "correct": true, "because": "Digital ersetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Digital Workplace nur für große Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen einen Digital Workplace?', 4, '[{"text": "Cloud-Computing", "correct": true, "because": "Flexibler Zugriff"}, {"text": "KI-Tools", "correct": true, "because": "Automatisierung"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Digital Workplace immer teuer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosteneffizient möglich"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Digital Workplace?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Fördert Nutzung"}, {"text": "Hohe Hardwarekosten", "correct": false, "because": "Effizienz zählt"}, {"text": "Lokale Installation", "correct": false, "because": "Cloud im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Digital Workplace fördert Teamarbeit. b) Er ersetzt alle Prozesse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prozesse bleiben teilweise"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen einen Digital Workplace effektiv?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Datenschutz wichtig"}, {"text": "Integration", "correct": true, "because": "Tools vernetzen"}, {"text": "Manuelle Updates", "correct": false, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Digital Workplace unwichtig?', 3, '[{"text": "Zugriff", "correct": false, "because": "Ortsunabhängig nötig"}, {"text": "Schnittstellen", "correct": false, "because": "Vernetzung essenziell"}, {"text": "Schreibtische", "correct": true, "because": "Physisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein Digital Workplace immer eine App?', 3, '[{"text": "Nein", "correct": true, "because": "Webbasiert möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Digital Workplace die Kultur verändert?', 2, '[{"text": "Ja", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Nein", "correct": false, "because": "Beeinflusst Arbeitsweise"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für einen Digital Workplace zentral?', 4, '[{"text": "Cloud-Zugriff", "correct": true, "because": "Flexibilität ermöglicht"}, {"text": "Lokale Server", "correct": false, "because": "Cloud im Fokus"}, {"text": "Papierdokumente", "correct": false, "because": "Digital ersetzt"}]');
